const input = $input.first().json;
const body = input.body || input;

// Support Shopify and WooCommerce webhook formats
const order = {
  order_id: body.id || body.order_id || body.number,
  email: body.email || body.customer?.email || body.billing?.email,
  first_name: body.customer?.first_name || body.billing?.first_name || '',
  last_name: body.customer?.last_name || body.billing?.last_name || '',
  phone: body.customer?.phone || body.billing?.phone || '',
  total: parseFloat(body.total_price || body.total || 0),
  currency: body.currency || 'IDR',
  items: (body.line_items || []).map(item => ({
    name: item.name || item.title,
    quantity: item.quantity,
    price: parseFloat(item.price)
  })),
  source: body.source_name || 'shopify',
  client_id: body.client_id
};

if (!order.email) return [{ json: { error: true, message: 'No email in order' } }];

return [{ json: order }];

const input = $input.first().json;
const body = input.body || input;

return [{ json: {
  email: body.email || body.customer_email,
  first_name: body.first_name || body.customer_name?.split(' ')[0] || '',
  cart_total: parseFloat(body.total || body.cart_total || 0),
  items: body.items || body.line_items || [],
  abandoned_at: body.abandoned_at || new Date().toISOString(),
  cart_url: body.cart_url || body.recovery_url || '',
  client_id: body.client_id
}}];
